import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import hmac

app = Flask(__name__)
UPLOAD_DIR = '/tmp/reports'
TEMPLATE_DIR = '/opt/app/templates'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')

os.makedirs(UPLOAD_DIR, exist_ok=True)

def verify_signature(payload, signature):
    expected = hmac.new(SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/v1/reports/generate', methods=['POST'])
def generate_report():
    """Generate PDF report from user-supplied LaTeX template name and variables."""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'JSON body required'}), 400

    template_name = data.get('template', 'quarterly')
    title = data.get('title', 'Report')
    author = data.get('author', 'System')
    content = data.get('content', '')

    # Validate template exists
    allowed_templates = ['quarterly', 'monthly', 'annual', 'custom']
    if template_name not in allowed_templates:
        return jsonify({'error': 'Invalid template'}), 400

    # Build LaTeX document with user-supplied content
    latex_source = f"""\\documentclass{{article}}
\\usepackage{{graphicx}}
\\usepackage{{hyperref}}
\\title{{{title}}}
\\author{{{author}}}
\\begin{{document}}
\\maketitle
{content}
\\end{{document}}"""

    # Write to temp file and compile
    report_id = hashlib.md5(latex_source.encode()).hexdigest()[:12]
    tex_path = os.path.join(UPLOAD_DIR, f'{report_id}.tex')
    pdf_path = os.path.join(UPLOAD_DIR, f'{report_id}.pdf')

    with open(tex_path, 'w') as f:
        f.write(latex_source)

    # Compile LaTeX to PDF
    result = subprocess.run(
        ['pdflatex', '-interaction=nonstopmode', '-output-directory', UPLOAD_DIR, tex_path],
        capture_output=True, text=True, timeout=30
    )

    if os.path.exists(pdf_path):
        return send_file(pdf_path, mimetype='application/pdf', as_attachment=True,
                        download_name=f'report_{report_id}.pdf')
    else:
        return jsonify({'error': 'Compilation failed', 'log': result.stdout[-500:]}), 500

@app.route('/api/v1/reports/list', methods=['GET'])
def list_reports():
    """List generated reports."""
    files = [f for f in os.listdir(UPLOAD_DIR) if f.endswith('.pdf')]
    return jsonify({'reports': files})

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

@app.route('/internal/cleanup', methods=['POST'])
def cleanup():
    """Remove old reports. Internal use only."""
    sig = request.headers.get('X-Internal-Signature', '')
    if not verify_signature('cleanup', sig):
        return jsonify({'error': 'unauthorized'}), 403
    count = 0
    for f in os.listdir(UPLOAD_DIR):
        os.remove(os.path.join(UPLOAD_DIR, f))
        count += 1
    return jsonify({'removed': count})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
